/**
 * 目的地详情数据 —— 逐城核实过的实用信息
 * 与 destinations.js 用 id 关联；id 必须一一对应。
 *
 * 字段说明：
 *  known     标题下的一句话定性（这里最容易踩坑的地方）
 *  hour      首屏参数条第 5 格：几点去最对
 *  spots     必去清单，与 destinations.js 的 mustSee 逐项对应
 *              name  景点名
 *              what  这是什么、值不值得、看什么重点
 *              way   怎么去 / 能不能预约 / 现场怎么排队
 *              time  开放时间
 *              fee   票价（核实过的数字）
 *              tips  现场怎么安排最舒服（时机、避坑）
 *  plan      逐日行程，days 是多少天就写几天
 *              t 日期标签 / d 一句话主题
 *               stops  [{ time, what }]  按时间排的动作
 *              note  这一天的关键提醒（选填）
 *  eats      吃什么，按用途分组
 *              k 分组名 / items [{ name, shop, price, how }]
 *  stay      住在哪一块，给两三处片区和价位
 *  budget    预算四行：住 / 吃 / 门票交通 / 机动
 *              k 名称 / v 金额 / note 这一行的具体构成
 *  cautions  临走前要知道的（节假日、闭馆日、天气、身体）
 *
 * 括号里的年份是核实时点，价格与时间会变，出发前复核一次官方渠道。
 */
