        "way": "衡阳市南岳区，从衡山西站坐旅游专线 20 分钟到山脚游客中心。需在「南岳衡山」公众号预约，门票和环保车分开买。",
        "time": "景区全天开放；环保车 07:00 — 17:00；索道 07:30 — 17:30",
        "fee": "门票旺季约 110 元（淡季约 80 元）；环保车往返约 90 元；索道单程约 40 元（旺季浮动）",
        "tips": "上山坐环保车到南天门，再走 1.5 小时到祝融峰，比全程徒步省一半时间。想看日出必须住山上或夜里上山，环保车不开夜班。南天门的牌坊是拍云海的好机位。"
