        "way": "井冈山主峰景区，从茨坪镇开车约 20 分钟。需在「井冈山旅游」公众号预约，景区门票通票含主峰。",
        "time": "08:00 — 17:00",
        "fee": "井冈山景区通票约 190 元（旺季浮动，含主峰、龙潭等）",
        "tips": "上午 9 点前雾还没散，峰在雾里反而好看。观景台正对五指峰，用广角拍能收全五座。雨后第二天最出片。"
