        "what": "从星村码头顺流到武夷宫，全长 9.5 公里，坐竹筏约 100 分钟，过九个弯。溪水最深处约 3 米，清到能看见河底的卵石。两岸是丹霞红岩，玉女峰、大王峰、三仰峰都在沿线，崖壁上还能看见古越人 3000 多年前的架壑船棺。艄公一路撑篙一路讲，讲得好不好决定这 100 分钟的质量。",
        "way": "星村码头（上游）上筏，武夷宫码头下。竹筏票须在景区官方渠道提前购买并选时段，旺季每天早上 6:00 放号，130 元一人，一筏 6 人。",
        "time": "7:30 — 16:00 分时段发筏（旺季延长）",
        "fee": "竹筏 130 元（不含景区门票，需另购 1 日票 140 元起或联票）",
        "tips": "选 8:00 — 9:00 那班：溪面上还有雾，光线斜，红岩的颜色最饱和。一筏 6 人拼坐，想拍全景坐最前面。艄公会讲段子，给 20 元小费讲得更细，这是行规。全程要穿一次性雨披，鞋会湿。"
