        "what": "海拔 2071 米的高山湖，面积 453 平方公里，是新疆海拔最高、面积最大的高山湖泊。它有个别称叫「大西洋的最后一滴眼泪」——这里是大西洋暖湿气流能到达的最东端。湖水蓝得发黑，是因为水深（最深 92 米）且含矿物质。环湖公路 90 公里，南岸的松树头一带能看见雪线一直压到湖面。",
        "way": "博尔塔拉州博乐市境内，从伊宁市出发约 150 公里、2 小时，走连霍高速。环湖公路可自驾，景区按车收费。没有直达班车，包车从伊宁往返约 800 元一天。",
        "time": "夏季 8:00 — 20:00（环湖公路全天可通行，夜间不建议）",
        "fee": "门票约 70 元、环湖自驾车约 100 元一辆（旺季浮动，以景区公示为准）",
        "tips": "从南门进、东门出是顺光方向，湖水在上午 9 到 11 点最蓝。东门那边大巴团最多，湖边栈道会挤。南岸点将台一带人少，可以停车走到水里。"
